    "tableId": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "관련 테이블 ID입니다." } },
    "order": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "테이블에서 필드의 순서입니다. 첫 번째 필드는 0입니다." } },
    "primary": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "필드가 기본 필드인지 여부를 나타냅니다. `true`인 경우 필드를 삭제할 수 없으며 값은 전체 행을 나타내야 합니다." } },
    "type": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "이 필드에 정의된 유형입니다." } },
    "extraProps": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "일부 추가 속성은 유형에 따라 다르므로 여기에서 설명되지 않습니다." } },
    "readOnly": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "필드가 읽기 전용 필드인지 여부를 나타냅니다. `true`인 경우 셀 값을 업데이트할 수 없습니다." } },
    "descriptionField": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "필드 설명" } }
