    "rowId": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "값과 관련된 행을 이동합니다." } },
    "before": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "제공된 값과 관련된 행 앞에 제공된 `row_id`와 관련된 행을 이동합니다. 제공되지 않으면 행은 끝으로 이동합니다." } }
